import { motion } from "motion/react";

function SpringDemo() {
  return (
    <motion.div
      animate={{ x: 200 }}
      transition={{
        type: "spring",
        stiffness: 300,
        damping: 20,
        mass: 1,
      }}
    />
  );
}

// Higher stiffness = snappier
// Higher damping = less bounce
// Higher mass = more inertia
